        """
        Transpile the predict method.

        Parameters
        ----------
        :param temp_type: string
            The kind of export type (embedded, separated, exported).

        Returns
        -------
        :return : string
            The transpiled predict method as string.
        """
        if temp_type == "embedded":
            return self._predict_embedded()
        elif temp_type == "separated":
            return self._predict_separated()
        elif temp_type == "exported":
            return self._predict_exported()
        else:
            raise ValueError("Unknown export type.")

